import type { KarakaAttribute, KarakaCategoryGroup, KarakaEntry } from "./types";

type Pair = [english: string, tamil: string];

function group(category: string, categoryTamil: string, pairs: Pair[]): KarakaCategoryGroup {
  return { category, categoryTamil, items: pairs.map(([en]) => en), itemsTa: pairs.map(([, ta]) => ta) };
}

function attr(label: string, value: string, valueTa: string): KarakaAttribute {
  return { label, value, valueTa };
}

